/** the subjects new with the screen-axis art (drawn from these views until their diagonal views exist): their ids */
export const AXIS_NEW: ReadonlySet<string> = new Set(["landscape:bush-deep-green","landscape:bush-golden-russet","landscape:bush-sage-round","landscape:flowerbed-daisies","landscape:flowerbed-lavender","landscape:flowerbed-marigolds","landscape:hydrangea-pale","ce:parking-garage-2storey","ce:parking-garage-3storey","ce:parking-garage-4storey","ce:parking-garage-5storey","ce:parking-garage-6storey"]);
/** Appended last: the screen-axis pictures on their own pages; a view takes its subject's studio size (a removed subject is left out) */
export function appendAxisViews(library: LibItem[], pages: string[][]) {
  const first = pages.length; pages.push(...PAGES.filter(p => p.length));
  const page = new Map<number, number>(); PAGES.forEach((p, i) => { if (p.length) page.set(i, first + page.size); });
  const have = new Set(library.map(o => o.id));
  for (const it of ITEMS) {
    const base = it.id.startsWith("view:") ? it.id.slice(5, it.id.lastIndexOf(":")) : it.id;
    if (removed.has(base) || removed.has(it.id) || have.has(it.id)) continue;
    library.push({ ...it, tex: [page.get(it.tex[0])!, ...it.tex.slice(1)] as LibItem["tex"] });
    // a heading: the size of its building (without the factor of the building picture) times its own factor (view-scales.json: the studio per-view size)
    if (it.id !== base && OWNER_SCALE[base] !== undefined && (OWNER_SCALE[it.id] === undefined || it.id in VIEW_FACTOR)) OWNER_SCALE[it.id] = +(OWNER_SCALE[base]! / (VIEW_FACTOR[base] ?? 1) * (VIEW_FACTOR[it.id] ?? 1)).toFixed(3);
  }
}
